def get(route: str) -> Endpoint:
    """Look up an endpoint; tolerates leading slashes and /api/ prefixes."""
    key = route.strip().strip("/")
    for prefix in ("api/", "weapi/", "eapi/", "xeapi/", "neapi/", "linuxapi/"):
        if key.startswith(prefix):
            key = key[len(prefix):]
            break
    key = key.split("?", 1)[0].split("#", 1)[0]
    if key in ENDPOINTS:
        return ENDPOINTS[key]
    for n in range(1, 10):
        candidate = f"v{n}/{key}"
        if candidate in ENDPOINTS:
            return ENDPOINTS[candidate]
    raise KeyError(f"unknown route: {route!r}")


def find(pattern: str) -> list[Endpoint]:
    """Case-insensitive substring search over all routes."""
    needle = pattern.lower()
    return [ep for r, ep in ENDPOINTS.items() if needle in r.lower()]


def summary() -> str:
    counts = {g: len(rs) for g, rs in GROUPS.items()}
    width = max((len(g) for g in counts), default=0)
    rows = [f"{len(ENDPOINTS)} routes / {len(GROUPS)} groups", ""]
    for g, n in counts.items():
        rows.append(f"{g:<{width}}  {n:>4}")
    return "\n".join(rows)
